import static co.aplomo.web.Html.escapar;
/** RF-014 a RF-020: una foto y una conversación, con los campos y motor actuales. */
final class ConversacionEvaluacion {
 private ConversacionEvaluacion(){}
 static String nueva(Sesion s,Evaluaciones.Contexto c,int id){String aviso=c.visita().empresaNombre().equals(co.aplomo.servicio.PracticaEvaluacion.NOMBRE)?"<div class=\"banner\" role=\"status\">Evaluación de práctica · Los resultados se guardan en la empresa de demostración. Puedes usar las fotos de ejemplo.</div>":"";return pagina(s,c.puestos(),id,c.visita().visita().id(),c.visita().empresaNombre()+" · "+c.visita().salonNombre()).replace("<form data-evaluacion",aviso+"<form data-evaluacion");}
 private static String pagina(Sesion s,List<Puesto> puestos,int id,int visita,String lugar){
  var p=puestos.stream().filter(x->x.id()==id).findFirst().orElse(null);if(id!=0&&p==null)throw new IllegalArgumentException("Elige un puesto activo del salón de esta visita.");
  StringBuilder h=new StringBuilder("<div class=\"pagehead\"><div><span class=\"eyebrow\">Evaluaciones · Nueva</span><h1>Nueva evaluación</h1><p class=\"hint\">").append(escapar(lugar)).append("</p></div><span class=\"tag\" data-modo>").append(p==null?"":p.tipo().equals("ESCRITORIO")?"Oficina":"Planta").append("</span></div><form data-evaluacion data-revision=\"si\" data-conversacion=\"si\" data-tour=\"campo\" data-fases=\"5\" action=\"/evaluaciones\" method=\"post\" enctype=\"multipart/form-data\" novalidate>").append(Html.csrf(s));
  oculto(h,"visita",""+visita);oculto(h,"recorrido","campo");for(String n:List.of("postura","motivo","criterio","minutos","condiciones_respondidas"))oculto(h,n,"");
  if(p!=null)h.append("<input type=\"hidden\" name=\"puesto\" value=\"").append(id).append("\" data-tarea=\"").append(escapar(p.descripcion())).append("\">");else{h.append("<label>Puesto de trabajo<select class=\"input\" name=\"puesto\"><option value=\"\">Elige un puesto</option>");for(var q:puestos)h.append("<option value=\"").append(q.id()).append("\" data-tarea=\"").append(escapar(q.descripcion())).append("\">").append(escapar(q.descripcion())).append("</option>");h.append("</select></label>");}
  h.append("<header class=\"campo-cabecera\"><h2 data-titulo-fijo>Bienvenida y consentimiento</h2><div class=\"row between\"><button class=\"btn\" type=\"button\" data-atras-evaluacion>← Atrás</button><span id=\"pasoActual\" role=\"status\">Paso 1 de 5</span><strong data-lado-titulo></strong></div><ol class=\"campo-progreso\" aria-label=\"Pasos de la evaluación\">");String[] nombres={"Permiso","Puesto","Postura 1","Postura 2","Resultado"};for(int i=0;i<5;i++)h.append("<li data-etapa=\"").append(i+1).append("\">").append(nombres[i]).append("</li>");h.append("</ol><progress max=\"5\" value=\"1\" aria-label=\"Avance de la evaluación\"></progress></header>");
  abrir(h,1,"Consentimiento");h.append(PaginasEvaluacion.opcion("acepta","si","Confirmo que la persona evaluada aceptó y firmó el consentimiento informado por escrito.","",true,"required",""));pregunta(h,"registro","","Permiso de fotos",new String[][]{{"CON_FOTOS","Sí, permite fotos"},{"SIN_REGISTRO_FOTOGRAFICO","No permite fotos"}});h.append("</section>");
  abrir(h,2,"Datos del puesto");String[][] tiempos={{"MENOS_2","Menos de 2 horas"},{"DE_2_A_4","De 2 a 4 horas"},{"DE_4_A_6","Más de 4 y hasta 6"},{"DE_6_A_8","Más de 6 y hasta 8"},{"MAS_8","Más de 8 horas"}};for(var t:tiempos)t[0]=""+MapeosCampo.MINUTOS.get(t[0]);pregunta(h,"tiempo_campo","Pregúntale","¿Cuántas horas al día trabaja en este puesto?",tiempos);
  h.append("<h3>Condiciones del puesto</h3><div class=\"campo-condiciones\">");for(var x:PaginasEvaluacion.CONDICIONES)h.append(PaginasEvaluacion.opcion(x[0],"si",x[1],"",true,"",""));h.append(PaginasEvaluacion.opcion("ninguna","si","Ninguna","",true,"","")).append("</div>").append(Formularios.texto(Map.of(),"observaciones","Otras observaciones (opcional)",255,false)).append("</section>");
  abrir(h,3,"Foto y ángulos");h.append("<div class=\"campo-dos-columnas\"><div class=\"campo-imagen\"><div data-muestra-perfil>").append(muestra("perfil","")).append("</div><div class=\"stack\" data-foto-revision hidden></div><div class=\"row\" data-foto-controles hidden><button type=\"button\" class=\"btn\" data-cambiar-foto>Cambiar foto</button><button type=\"button\" class=\"btn\" data-quitar-foto>Quitar foto</button></div></div><div class=\"campo-panel\"><div data-subir-perfil><p>Fotografía a la persona de lado, con el cuerpo completo, en su postura real y con el brazo a la vista. Pon la cámara a la altura de la cadera.</p><p data-instruccion-postura>Pídele al trabajador que se ponga en la postura en la que se siente más incómodo y tómale la foto.</p><button class=\"btn p\" type=\"button\" data-perfil>Subir foto</button>"+GaleriaDemo.selector("PERFIL")+"<input type=\"file\" hidden accept=\"image/jpeg,image/png\" data-archivo-perfil></div><div class=\"campo-compacta\" data-medidas-compactas hidden>");
  for(String k:List.of("BRAZO","ANTEBRAZO","CUELLO","TRONCO")){
   String img=RecorridoCuerpo.RANGOS.get(Segmento.valueOf(k)).get(0).imagen();h.append("<div class=\"campo-medida\" data-medida=\"").append(k).append("\"><img class=\"campo-silueta\" src=\"/static/img/tour/").append(img).append("\" alt=\"\"><div><span data-angulo=\"").append(k).append("\">Sin medir</span><span class=\"tag\" data-revisar hidden>Revisar</span>");String[][] opciones=RecorridoCuerpo.RANGOS.get(Segmento.valueOf(k)).stream().map(x->new String[]{""+x.grados(),x.etiqueta()}).toArray(String[][]::new);pregunta(h,"rango_"+k,"",nombre(k),opciones);h.append("</div></div>");
  }
  h.append("<div class=\"campo-ajustes\"><span class=\"eyebrow\">Míralo</span><h3>Marca lo que veas</h3><div class=\"campo-chips\">");
  for(var x:new String[][]{{"hombroElevado","Hombro subido en el brazo que hace el esfuerzo"},{"brazoSeparado","Brazo que hace el esfuerzo separado del cuerpo"},{"brazoApoyado","Brazo que hace el esfuerzo apoyado"},{"antebrazoCruza","Antebrazo del brazo que hace el esfuerzo cruza el cuerpo o sale hacia un lado"},{"cuelloGirado","Cabeza torcida"},{"cuelloInclinado","Cabeza inclinada hacia un lado"},{"troncoGirado","Espalda torcida"},{"troncoInclinado","Espalda inclinada hacia un lado"},{"pies_sin_apoyo","Pies sin buen apoyo"}})chip(h,x[0],x[1]);h.append("</div>");h.append("<p>Si no marcas nada, se cuenta como que no hay ajuste.</p>");
  h.append("<fieldset class=\"campo-muneca\"><legend>Muñeca</legend><input type=\"hidden\" name=\"muneca_campo\"><div class=\"campo-chips\">");for(var x:new String[][]{{"RECTA","Recta"},{"POCO","Un poco doblada"},{"MUCHO","Muy doblada"}})h.append("<button type=\"button\" class=\"campo-chip\" data-muneca=\"").append(MapeosCampo.MUNECA.get(x[0])).append("\" aria-pressed=\"false\">").append(x[1]).append("</button>");chip(h,"munecaDesviada","Torcida hacia un lado");chip(h,"giro_extremo","Giro hasta el límite");h.append("</div></fieldset></div><h3>Esfuerzo y carga</h3>");
  pregunta(h,"carga_campo","","Carga",new String[][]{{"CELULAR","No aplica"},{"GALON","De 2 a 10 kg"},{"BULTO","Más de 10 kg"}});pregunta(h,"actividad_campo","","Esfuerzo muscular",new String[][]{{"NINGUNA","No aplica"},{"ESTATICA","Mantiene la postura más de 1 minuto"},{"REPETITIVA","Repite el movimiento más de 4 veces por minuto"}});pregunta(h,"tirones_campo","","Golpes o tirones",new String[][]{{"no","No aplica"},{"si","Sí hay golpes o tirones"}});
  h.append("</div></div></div></div>").append(apoyo()).append("<div data-mapeos hidden>");for(String peso:List.of("CELULAR","GALON","BULTO"))for(String act:List.of("NINGUNA","ESTATICA","REPETITIVA"))for(boolean golpe:new boolean[]{false,true})h.append("<i data-peso=\"").append(peso).append("\" data-actividad=\"").append(act).append("\" data-golpe=\"").append(golpe?"si":"no").append("\" data-carga=\"").append(MapeosCampo.carga(peso,act,golpe).name()).append("\"></i>");
  for(String parte:List.of("cuello","tronco"))for(String tipo:List.of("GIRADA","INCLINADA","AMBAS")){var valores=MapeosCampo.orientacion("si",tipo);h.append("<i data-orientacion=\"").append(parte).append("\" data-tipo=\"").append(tipo).append("\" data-girada=\"").append(valores[0]).append("\" data-inclinada=\"").append(valores[1]).append("\"></i>");}h.append("</div></section>");
  abrir(h,5,"Resultado");h.append("<h3 data-resumen-titulo hidden>Resumen del puesto</h3><div data-resultados></div></section><div class=\"aviso\" role=\"alert\" data-error-evaluacion hidden><h3 data-error-titulo>Revisa los datos</h3><span data-error-texto></span><div class=\"row\" data-error-foto-acciones hidden><button type=\"button\" class=\"btn\" data-foto-reemplazar>Subir otra</button><button type=\"button\" class=\"btn\" data-foto-manual>Marcar a mano</button><button type=\"button\" class=\"btn\" data-foto-usar>Usar esta de todos modos</button></div><button type=\"button\" class=\"link\" data-cerrar-error>Cerrar</button></div><div class=\"wizfoot\"><p class=\"hint\" role=\"status\" data-falta></p><span class=\"seguir-zona\" data-seguir-zona><button type=\"button\" class=\"btn p\" data-siguiente disabled>Seguir →</button></span><button type=\"submit\" class=\"btn p\" data-guardar-volver hidden>Guardar y terminar</button><button type=\"submit\" class=\"link\" data-agregar-postura hidden>Agregar otra postura</button></div><div data-editor-compatibilidad hidden>");String editor=PaginasAnalisis.pasos();h.append(editor.substring(0,editor.indexOf("<section class=\"card stack\" data-paso=\"6\"")).replace("data-paso=","data-editor-paso=")).append("</div></form>").append(PaginasAnalisis.scripts());return Html.pagina("Nueva evaluación",PaginasEvaluacion.fases(h.toString()),s,false,false);
 }
 private static void oculto(StringBuilder h,String n,String v){h.append("<input type=\"hidden\" name=\"").append(n).append("\" value=\"").append(escapar(v)).append("\">");}
 private static void abrir(StringBuilder h,int n,String t){
  h.append("<section class=\"card stack conversacion-pantalla\" data-paso=\"").append(n).append("\"").append(n==1?"":" hidden").append("><div class=\"campo-titulo\"><h2>").append(t).append("</h2></div>");
  if(n==3)h.append("<div class=\"campo-postura-aviso\" role=\"status\" data-postura-aviso></div><div class=\"campo-chips\" role=\"group\" aria-label=\"Brazo que hace el esfuerzo\"><span>Brazo que hace el esfuerzo:</span><button type=\"button\" class=\"campo-chip\" data-lado-campo=\"DERECHO\" aria-pressed=\"true\">Derecho</button><button type=\"button\" class=\"campo-chip\" data-lado-campo=\"IZQUIERDO\" aria-pressed=\"false\">Izquierdo</button><button type=\"button\" class=\"campo-chip\" data-lado-campo=\"AMBOS\" aria-pressed=\"false\">Ambos</button></div><p role=\"status\" data-perfil-otro hidden>Sube el perfil del otro lado del cuerpo.</p>");
 }
 private static void chip(StringBuilder h,String nombre,String texto){h.append("<label class=\"campo-chip\"><input type=\"checkbox\" data-chip=\"").append(nombre).append("\"><span>").append(texto).append("</span></label>");}
 private static void pregunta(StringBuilder h,String n,String voz,String t,String[][] opciones){String defecto=Set.of("carga_campo","actividad_campo","tirones_campo").contains(n)?opciones[0][0]:"";h.append("<div class=\"campo-pregunta\" data-pregunta=\"").append(n).append("\">");if(!voz.isEmpty())h.append("<span class=\"eyebrow\">").append(voz).append("</span>");h.append("<p id=\"pregunta-").append(n).append("\"><em>“").append(t).append("”</em></p>");h.append("<input type=\"hidden\" name=\"").append(n).append("\" value=\"").append(defecto).append("\"><button class=\"campo-respuesta\" type=\"button\" aria-expanded=\"false\" aria-controls=\"opciones-").append(n).append("\" aria-labelledby=\"pregunta-").append(n).append(" respuesta-").append(n).append("\" data-abrir=\"").append(n).append("\"><span id=\"respuesta-").append(n).append("\">").append(defecto.isEmpty()?"Elige una opción":"No aplica ✓").append("</span><span aria-hidden=\"true\">⌄</span></button><div class=\"campo-lista\" id=\"opciones-").append(n).append("\" hidden>");for(var x:opciones){h.append("<button type=\"button\" class=\"campo-opcion\" data-respuesta=\"").append(n).append("\" data-valor=\"").append(escapar(x[0])).append("\" aria-pressed=\"").append(x[0].equals(defecto)).append("\">");if(x.length>2)h.append("<img src=\"/static/img/tour/").append(x[2]).append("\" alt=\"\">");h.append("<span>").append(escapar(x[1])).append("</span></button>");}h.append("</div></div>");}
 private static String muestra(String tipo,String leyenda){return "<figure class=\"campo-muestra\"><img src=\"/static/img/muestra_"+tipo+".jpg\" alt=\"Ejemplo de foto de "+tipo+"\">"+(leyenda.isEmpty()?"":"<figcaption>"+leyenda+"</figcaption>")+"</figure>";}
 private static String apoyo(){StringBuilder h=new StringBuilder("<details class=\"campo-apoyo\"><summary class=\"btn agregar-foto\"><span aria-hidden=\"true\">+</span> Agregar otra foto (opcional)</summary><div class=\"campo-chips\"><button type=\"button\" class=\"campo-chip\" data-apoyo-tipo=\"FRENTE\" aria-pressed=\"true\">Frente</button><button type=\"button\" class=\"campo-chip\" data-apoyo-tipo=\"OTRA\" aria-pressed=\"false\">Detalle</button></div>");for(String vista:List.of("FRENTE","OTRA")){String tipo=vista.equals("FRENTE")?"frente":"detalle";h.append("<div data-apoyo-panel=\"").append(vista).append("\"").append(vista.equals("FRENTE")?"":" hidden").append(">").append(muestra(tipo,vista.equals("FRENTE")?"De frente, cuerpo completo. Solo respaldo.":"Mano y muñeca de cerca. Solo respaldo.")).append("<button type=\"button\" class=\"btn\" data-agregar=\"").append(vista).append("\">Subir foto</button>").append(GaleriaDemo.selector(vista)).append("<input type=\"file\" hidden accept=\"image/jpeg,image/png\" data-archivo-extra=\"").append(vista).append("\"><div data-apoyo-vista=\"").append(vista).append("\"></div></div>");}return h.append("</details>").toString();}
 private static String nombre(String k){return switch(k){case "ANTEBRAZO"->"Antebrazo";case "CUELLO"->"Cuello";case "TRONCO"->"Tronco";default->"Brazo";};}
 static String continuar(Sesion s,Evaluaciones.Consulta c){var f=c.ficha();var d=f.datos();var p=new Puesto(f.puesto(),0,null,null,f.numero(),d.postura(),"","",null,true);String html=pagina(s,List.of(p),p.id(),f.visita(),"Evaluación existente · Puesto "+f.numero());html=html.replace("<span class=\"tag\" data-modo>Planta</span>","");html=html.replace("action=\"/evaluaciones\"","data-criterio=\""+escapar(d.criterio())+"\" data-continuar=\""+f.id()+"\" action=\"/evaluaciones/"+f.id()+"/analisis\"");StringBuilder fotos=new StringBuilder("<div data-fotos-existentes hidden>");for(var foto:c.fotos())if(!foto.descripcion().startsWith(co.aplomo.servicio.FotosEvaluacion.REEMPLAZADA))fotos.append("<span data-foto-id=\"").append(foto.id()).append("\" data-vista=\"").append(foto.vista()).append("\" data-descripcion=\"").append(escapar(foto.descripcion())).append("\" data-src=\"/fotos/").append(foto.id()).append("\"></span>");return html.replace("</form>",fotos.append("</div></form>").toString());}
}
